<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { useAuthenticationStore } from '../../stores/authentication/store'
import { departService } from '../../services/depart/service'
import { destinationService } from '../../services/destination/service'
import { gareService } from '../../services/gare/service'
import type { PublicProgramme } from '../../models/depart/model'
import type { PublicDestination } from '../../models/destination/model'
import type { PublicGare, PublicGareCooperative } from '../../models/gare/model'
import { localIsoDate } from '../../utils/date'

const route = useRoute()
const router = useRouter()
const auth = useAuthenticationStore()
const today = localIsoDate()
const loading = ref(true)
const error = ref('')
const mobileMenuOpen = ref(false)
const destinations = ref<PublicDestination[]>([])
const gares = ref<PublicGare[]>([])
const programme = ref<PublicProgramme[]>([])
const total = ref(0)
const sortBy = ref<'time' | 'price' | 'availability'>('time')
const sortOrder = ref<'asc' | 'desc'>('asc')
const filters = reactive({ from: value('from'), to: value('to'), date: value('date', today), dateTo: value('dateTo'), passengers: value('passengers', '1'), gare: value('gare'), cooperative: value('cooperative'), search: value('search') })

function value(name: string, fallback = '') { const item = route.query[name]; return typeof item === 'string' ? item : fallback }
const cooperativeOptions = computed<PublicGareCooperative[]>(() => {
  const source = filters.gare ? gares.value.filter((item) => item.id === Number(filters.gare)) : gares.value
  const map = new Map<number, PublicGareCooperative>(); source.flatMap((item) => item.cooperatives).forEach((item) => map.set(item.id, item)); return [...map.values()].sort((a, b) => a.nom.localeCompare(b.nom))
})
const sortedProgramme = computed(() => [...programme.value].sort((left, right) => {
  const comparison = sortBy.value === 'price' ? Number(left.tarif?.prix || 0) - Number(right.tarif?.prix || 0) : sortBy.value === 'availability' ? left.places_disponibles - right.places_disponibles : `${left.date_depart}T${left.heure_depart}`.localeCompare(`${right.date_depart}T${right.heure_depart}`)
  return sortOrder.value === 'asc' ? comparison : -comparison
}))
function displayDate(value: string) { return new Intl.DateTimeFormat('fr-FR', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' }).format(new Date(`${value}T00:00:00`)) }
function displayPrice(item: PublicProgramme) { return item.tarif ? `${Number(item.tarif.prix).toLocaleString('fr-FR')} ${item.tarif.devise}` : 'Tarif à confirmer' }
function query() { return { from: filters.from || undefined, to: filters.to || undefined, date: filters.date || undefined, dateTo: filters.dateTo || undefined, passengers: filters.passengers, gare: filters.gare || undefined, cooperative: filters.cooperative || undefined, search: filters.search || undefined } }
function swapLocations() { const from = filters.from; filters.from = filters.to; filters.to = from }
function reserve(item: PublicProgramme) { void router.push({ name: 'public-booking', query: { depart_id: String(item.id) } }) }
function goToSpace() { void router.push({ name: auth.user?.role?.toLowerCase() === 'passenger' ? 'client-space' : 'home' }) }
function reset() { filters.from = ''; filters.to = ''; filters.date = today; filters.dateTo = ''; filters.passengers = '1'; filters.gare = ''; filters.cooperative = ''; filters.search = ''; void search() }
async function loadReferences() {
  const [destinationResult, gareResult] = await Promise.allSettled([destinationService.publicList({ page: 1, page_size: 200 }), gareService.publicList({ page: 1, page_size: 100 })])
  if (destinationResult.status === 'fulfilled') destinations.value = destinationResult.value.items || []
  if (gareResult.status === 'fulfilled') gares.value = gareResult.value.items || []
}
async function loadProgramme() {
  loading.value = true; error.value = ''
  try { const result = await departService.publicProgramme({ page: 1, page_size: 100, search: filters.search || undefined, date_from: filters.date || undefined, date_to: filters.dateTo || undefined, id_destination_depart: filters.from ? Number(filters.from) : undefined, id_destination_arrivee: filters.to ? Number(filters.to) : undefined, id_gare: filters.gare ? Number(filters.gare) : undefined, id_cooperative: filters.cooperative ? Number(filters.cooperative) : undefined, passagers: Number(filters.passengers) }); programme.value = result.items || []; total.value = result.total || 0 }
  catch (value) { console.error('[PUBLIC_RESULTS_ERROR]', value); error.value = 'Les départs ne sont pas disponibles pour le moment.' }
  finally { loading.value = false }
}
async function search() { await router.replace({ name: 'search-results', query: query() }); await loadProgramme() }
onMounted(async () => { await loadReferences(); await loadProgramme() })
</script>

<template>
  <main class="travel-results"><header class="results-header"><RouterLink class="travel-brand" to="/"><span class="travel-brand-mark">C</span><strong>Coopérative</strong></RouterLink><label class="global-search"><span>⌕</span><input v-model="filters.search" type="search" placeholder="Rechercher un trajet, une gare…" aria-label="Rechercher un trajet" @keyup.enter="search"></label><nav class="results-nav"><RouterLink to="/">Accueil</RouterLink><a href="#results">Voyages</a><a href="#help">Aide</a></nav><div class="results-actions"><button class="results-menu" type="button" :aria-label="mobileMenuOpen ? 'Fermer le menu' : 'Ouvrir le menu'" :aria-expanded="mobileMenuOpen" @click="mobileMenuOpen = !mobileMenuOpen">☰</button><button v-if="auth.isAuthenticated" class="results-login" type="button" @click="goToSpace">Mon espace</button><RouterLink v-else class="results-login" to="/login">Connexion</RouterLink><RouterLink v-if="!auth.isAuthenticated" class="results-signup" to="/register">Créer un compte</RouterLink></div></header><nav v-if="mobileMenuOpen" class="results-mobile-nav"><RouterLink to="/">Accueil</RouterLink><a href="#results">Voyages</a><a href="#help">Aide</a></nav>
    <section class="results-hero"><div><RouterLink class="results-back" to="/">← Modifier la recherche</RouterLink><p class="results-eyebrow">VOYAGES DISPONIBLES</p><h1>Comparez les départs.</h1><p>Les horaires, tarifs, gares, coopératives et places disponibles sont réunis dans chaque résultat.</p></div></section>
    <section class="results-query"><form @submit.prevent="search"><div class="query-heading"><strong>Modifier votre recherche</strong><button class="swap-query" type="button" @click="swapLocations">↕ Inverser le trajet</button></div><div class="query-fields"><label><span>Départ</span><select v-model="filters.from"><option value="">Toutes les villes</option><option v-for="item in destinations" :key="`from-${item.id}`" :value="String(item.id)">{{ item.nom }}</option></select></label><label><span>Destination</span><select v-model="filters.to"><option value="">Toutes les villes</option><option v-for="item in destinations" :key="`to-${item.id}`" :value="String(item.id)">{{ item.nom }}</option></select></label><label><span>Date</span><input v-model="filters.date" type="date" :min="today"></label><label><span>Passagers</span><select v-model="filters.passengers"><option v-for="count in 8" :key="count" :value="String(count)">{{ count }}</option></select></label><button type="submit">Rechercher →</button></div></form></section>
    <section id="results" class="results-body"><aside class="results-filters"><div><p class="results-eyebrow">AFFINER</p><h2>Votre recherche</h2></div><label>Gare<select v-model="filters.gare" @change="filters.cooperative = ''"><option value="">Toutes les gares</option><option v-for="item in gares" :key="item.id" :value="String(item.id)">{{ item.nom }} · {{ item.ville }}</option></select></label><label>Coopérative<select v-model="filters.cooperative"><option value="">Toutes les coopératives</option><option v-for="item in cooperativeOptions" :key="item.id" :value="String(item.id)">{{ item.nom }}</option></select></label><button class="filter-apply" type="button" @click="search">Appliquer les filtres</button><button class="filter-reset" type="button" @click="reset">Réinitialiser</button><div class="filter-note"><strong>Réservation sans compte</strong><span>Vous pouvez réserver librement. Une avance minimale de 25 % est demandée.</span></div></aside><div class="results-list"><div class="results-heading"><div><p class="results-eyebrow">RÉSULTATS</p><h2>{{ total }} départ{{ total > 1 ? 's' : '' }}</h2></div><label class="sort-control">Trier par<select v-model="sortBy"><option value="time">Horaire</option><option value="price">Prix</option><option value="availability">Disponibilité</option></select></label><button class="sort-order" type="button" @click="sortOrder = sortOrder === 'asc' ? 'desc' : 'asc'">{{ sortOrder === 'asc' ? '↑' : '↓' }}</button></div><div v-if="loading" class="result-loading"><i v-for="item in 3" :key="item"></i></div><div v-else-if="error" class="result-empty" role="alert"><strong>{{ error }}</strong><span>Modifiez vos critères puis relancez la recherche.</span><button type="button" @click="reset">Réinitialiser</button></div><div v-else-if="!sortedProgramme.length" class="result-empty"><strong>Aucun départ ne correspond à votre recherche.</strong><span>Essayez une autre date, une autre ville ou moins de passagers.</span><button type="button" @click="reset">Voir tous les départs</button></div><div v-else class="result-cards"><article v-for="item in sortedProgramme" :key="item.id" class="result-offer"><div class="result-time"><strong>{{ item.heure_depart?.slice(0, 5) }}</strong><span>{{ displayDate(item.date_depart) }}</span></div><div class="result-trip"><div><strong>{{ item.itineraire?.destination_depart?.nom || 'Départ' }}</strong><small>Ville de départ</small></div><b>→</b><div><strong>{{ item.itineraire?.destination_arrivee?.nom || 'Destination' }}</strong><small>Destination</small></div></div><div class="result-details"><span><small>Gare</small><strong>{{ item.gare?.nom || 'À confirmer' }}</strong></span><span><small>Coopérative</small><strong>{{ item.cooperative?.nom || 'À confirmer' }}</strong></span><span><small>Places</small><strong>{{ item.places_disponibles }} disponible{{ item.places_disponibles > 1 ? 's' : '' }}</strong></span></div><div class="result-price"><small>Tarif par place</small><strong>{{ displayPrice(item) }}</strong><button type="button" @click="reserve(item)">Voir et réserver →</button></div></article></div></div></section><section id="help" class="results-help"><strong>Besoin d’aide ?</strong><span>Après votre réservation, l’avance est payée par mobile money. Le billet est disponible lorsque le paiement est confirmé.</span><RouterLink to="/conditions-voyage">Conditions de voyage →</RouterLink></section>
  </main>
</template>

