mns:105px minmax(170px,.85fr) minmax(190px,1fr) 145px;align-items:center;gap:1rem;padding:1rem;border:1px solid #e2e9ed;border-radius:.6rem;background:#fff;box-shadow:0 8px 22px #18324b08;transition:transform .2s,box-shadow .2s}.result-offer:hover{transform:translateY(-2px);box-shadow:0 14px 28px #18324b14}.result-time{display:grid;gap:.25rem;border-right:1px solid #edf1f3}.result-time strong{color:#123452;font:800 1.5rem Manrope,sans-serif}.result-time span{color:#7e8e99;font-size:.64rem;text-transform:capitalize}.result-trip{display:flex;align-items:center;justify-content:center;gap:.65rem;text-align:center}.result-trip div{display:grid;gap:.25rem}.result-trip strong{color:#123452;font:800 .9rem Manrope,sans-serif}.result-trip small{color:#8797a1;font-size:.62rem}.result-trip>b{color:#ed812e}.result-details{display:grid;grid-template-columns:repeat(3,1fr);gap:.55rem}.result-details span{display:grid;gap:.25rem;min-width:0}.result-details small{color:#9aa7b0;font-size:.6rem;text-transform:uppercase}.result-details strong{overflow:hidden;color:#4f6879;font-size:.7rem;text-overflow:ellipsis;white-space:nowrap}.result-price{display:grid;justify-items:end;gap:.2rem;border-left:1px solid #edf1f3;padding-left:1rem}.result-price small{color:#9aa7b0;font-size:.6rem}.result-price strong{color:#df6e27;font-size:.88rem}.result-price button{min-height:34px;margin-top:.35rem;padding:0 .6rem}.result-empty{display:grid;justify-items:center;gap:.55rem;padding:3rem 1rem;border:1px dashed #ccd9e0;border-radius:.6rem;color:#718494;background:#fff;text-align:center}.result-empty strong{color:#18324b}.result-empty button{min-height:36px;margin-top:.4rem;border:1px solid #f0a86d;border-radius:.4rem;color:#df702b;background:#fff;font-weight:900;cursor:pointer}.result-loading{display:grid;gap:.75rem}.result-loading i{height:112px;border-radius:.6rem;background:linear-gradient(90deg,#fff 25%,#edf2f4 38%,#fff 63%);background-size:400% 100%;animation:loading 1.4s ease infinite}.results-help{